parameters.inputSchema:
{
  "name": "video_script_array_schema",
  "schema": {
    "type": "object",
    "properties": {
      "video_scripts": {
        "type": "array",
        "description": "An array of video scripts.",
        "items": {
          "type": "object",
          "properties": {
            "AngleHeadline": {
              "type": "string",
              "description": "String mostly 1 liner the headline"
            },
            "ConceptSummary": {
              "type": "string",
              "description": "String, expressive and articulate"
            },
            "VSLStructure": {
              "type": "string",
              "description": "String, markdown if required descriptive"
            },
            "VideoSuggestion": {
              "type": "string",
              "description": "Provide potential visual themes, scenes, or references (briefly)"
            },
            "EmotionalTriggers": {
              "type": "string",
              "description": "String, descriptive can be in markdown format"
            },
            "DirectResponseTechniques": {
              "type": "string",
              "description": "String, descriptive"
            },
            "CognitiveBiasesLeveraged": {
              "type": "string",
              "description": "String, descriptive explanation of the cognitive biases utilized"
            }
          },
          "required": [
            "AngleHeadline",
            "ConceptSummary",
            "VSLStructure",
            "VideoSuggestion",
            "EmotionalTriggers",
            "DirectResponseTechniques",
            "CognitiveBiasesLeveraged"
          ],
          "additionalProperties": false
        }
      }
    },
    "required": [
      "video_scripts"
    ],
    "additionalProperties": false
  },
  "strict": true
}

